mapper.select:
/* IResidentBoardNoticeMapper.selectResidentBoardNoticeCount */ SELECT COUNT(*) FROM apt_ann_board_post aabp INNER JOIN apt_board_instance abi ON aabp.board_no = abi.board_no WHERE aabp.del_yn = 'N' AND abi.use_yn = 'Y' AND abi.board_ty_cd = 'NOTICE' AND abi.apt_cmplex_no = #{aptCmplexNo}
AND aabp.ttl LIKE '%' || #{searchTtl} || '%'
AND TRUNC(aabp.reg_dttm) >= TO_DATE(#{searchStartDt}, 'YYYY-MM-DD')
AND TRUNC(aabp.reg_dttm) <= TO_DATE(#{searchEndDt}, 'YYYY-MM-DD')

/* IResidentBoardNoticeMapper.selectResidentBoardNoticeList */ SELECT * FROM ( SELECT rownum rnum , notice_list.* FROM ( SELECT aabp.ann_no , aabp.board_no , abi.apt_cmplex_no , aabp.ttl , aabp.wrtr_id , TO_CHAR(aabp.reg_dttm, 'YYYY-MM-DD') reg_dttm , TO_CHAR(aabp.mdf_dttm, 'YYYY-MM-DD') mdf_dttm , NVL(aabp.inq_cnt, 0) inq_cnt , aabp.del_yn , aabp.atch_file_id , abi.board_ty_cd , abi.board_nm , af.file_og_name , aabp.top_fix_yn FROM apt_ann_board_post aabp INNER JOIN apt_board_instance abi ON aabp.board_no = abi.board_no LEFT OUTER JOIN attach_file af ON TO_CHAR(af.file_group_no) = aabp.atch_file_id AND af.file_sort_order = 1 LEFT OUTER JOIN attach_file af ON TO_CHAR(af.file_group_no) = aabp.atch_file_id AND af.file_sort_order = 1 WHERE aabp.del_yn = 'N' AND abi.use_yn = 'Y' AND abi.board_ty_cd = 'NOTICE' AND abi.apt_cmplex_no = #{aptCmplexNo}
AND aabp.ttl LIKE '%' || #{searchTtl} || '%'
AND TRUNC(aabp.reg_dttm) >= TO_DATE(#{searchStartDt}, 'YYYY-MM-DD')
AND TRUNC(aabp.reg_dttm) <= TO_DATE(#{searchEndDt}, 'YYYY-MM-DD')
ORDER BY aabp.top_fix_yn DESC , aabp.reg_dttm DESC , TO_NUMBER(REGEXP_REPLACE(aabp.ann_no, '[^0-9]', '')) DESC ) notice_list WHERE rownum <= #{endRow} ) WHERE rnum >= #{startRow}

mapper.update:
/* IResidentBoardNoticeMapper.updateResidentBoardNoticeInqCnt */
UPDATE apt_ann_board_post
SET inq_cnt = NVL(inq_cnt, 0) + 1
WHERE ann_no = #{annNo}
  AND del_yn = 'N'
  AND board_no IN (
    SELECT board_no
    FROM apt_board_instance
    WHERE apt_cmplex_no = #{aptCmplexNo}
      AND board_ty_cd = 'NOTICE'
      AND use_yn = 'Y'
)
